function renderLibraryTree(){const search=$('library-search').value.trim().toLowerCase();const lang=state.settings.language;const filtered=state.libraries.filter(l=>l.language===lang&&l.name.toLowerCase().includes(search));function row(lib){return `<div class="library-row ${lib.id===state.activeLibrary?'active':''}"><button data-library="${esc(lib.id)}${bi("\" title=\"打开 ","\" title=\"Open ")}${esc(lib.name)}"><span class="lib-dot"></span><span class="lib-name">${esc(lib.name)}</span><span class="lib-count">${lib.words.length}</span></button>${!lib.builtin?`<button class="mini-action" data-edit-lib="${esc(lib.id)}${bi("\" aria-label=\"管理 ","\" aria-label=\"Manage ")}${esc(lib.name)}">${icon('edit')}</button>`:''}</div>`;}
const builtins=filtered.filter(l=>l.builtin);let html=lang==='en'?`<button class="tree-heading" data-section="builtin" aria-expanded="${!collapsedFolders.has('builtin')}">${icon(collapsedFolders.has('builtin')?'chevron-right':'chevron-down')}${bi("内置语料库<small>只读</small></button><div ","Built-in libraries<small>Read-only</small></button><div ")}${collapsedFolders.has('builtin')?'hidden':''}><div class="tree-subtitle">${icon('sparkles')} 流星雨语料库</div><div class="tree-items">${builtins.map(row).join('')||bi("<p class=\"empty-state\">正在载入原始词库</p>","<p class=\"empty-state\">Loading the original libraries</p>")}</div></div>`:'';
html+=`<button class="tree-heading" data-section="custom" aria-expanded="${!collapsedFolders.has('custom')}">${icon(collapsedFolders.has('custom')?'chevron-right':'chevron-down')}${icon('folder')}${bi(" 我的词库</button><div "," My libraries</button><div ")}${collapsedFolders.has('custom')?'hidden':''}>${filtered.filter(l=>!l.builtin&&!l.folderId).map(row).join('')}`;
for(const folder of state.folders){const libs=filtered.filter(l=>l.folderId===folder.id);if(search&&!libs.length&&!folder.name.toLowerCase().includes(search))continue;html+=`<div class="folder-heading"><button class="icon-button" data-fold-folder="${esc(folder.id)}${bi("\" aria-label=\"折叠或展开 ","\" aria-label=\"Collapse or expand ")}${esc(folder.name)}" aria-expanded="${!collapsedFolders.has(folder.id)}">${icon(collapsedFolders.has(folder.id)?'chevron-right':'chevron-down')}</button><button class="tree-heading" data-folder="${esc(folder.id)}${bi("\" title=\"打开文件夹","\" title=\"Open folder")}${state.settings.autoFolder?bi("并自动播放"," and autoplay"):''}">${icon('folder')} ${esc(folder.name)}<small>${libs.length}</small></button><button class="icon-button" data-edit-folder="${esc(folder.id)}${bi("\" aria-label=\"管理文件夹 ","\" aria-label=\"Manage folder ")}${esc(folder.name)}">${icon('edit')}</button></div><div class="folder-items" ${collapsedFolders.has(folder.id)?'hidden':''}>${libs.map(row).join('')||bi("<p class=\"empty-state\">还没有词库<br>可在词库管理中移入</p>","<p class=\"empty-state\">No libraries yet<br>Move a library here from Library manager</p>")}</div>`;}
html+='</div>';$('library-tree').innerHTML=html;$('history-count').textContent=state.history.length;}
