function renderPlayback(){document.body.classList.toggle('playing',playing);$('play-toggle').innerHTML=icon(playing?'pause':'play');$('play-toggle').setAttribute('aria-label',playing?bi("暂停播放","Pause playback"):mode==='spell'?bi("再读当前单词","Replay current word"):bi("开始播放","Start playback"));$('loop-toggle').classList.toggle('active',state.settings.loop);$('loop-toggle').setAttribute('aria-pressed',String(state.settings.loop));$('order-toggle').classList.toggle('active',state.settings.shuffle);$('order-toggle').title=state.settings.shuffle?bi("乱序播放","Shuffle"):bi("正序播放","Sequential playback");$('order-toggle').setAttribute('aria-label',state.settings.shuffle?bi("切换正序播放","Switch to sequential playback"):bi("切换乱序播放","Switch to shuffle"));}
