function recordingLink(url,label){try{const target=new URL(url);if(['https:','http:'].includes(target.protocol))return '<a href="'+esc(target.href)+'" target="_blank" rel="noopener noreferrer">'+esc(label)+'</a>';}catch{}return esc(label);}
function recordingAttributionHTML(){
 const recording=voice.lastRecording;
 if(!recording)return bi("<p class=\"hint\">播放后，这里显示读音来源；词典录音会附上作者和许可。</p>","<p class=\"hint\">After playback, this area shows the audio source. Dictionary recordings include attribution and license details.</p>");
 if(recording.kind==='free-api'){
  const provider=recording.sourceUrl?recordingLink(recording.sourceUrl,bi("Microsoft Edge 在线语音","Microsoft Edge online speech")):bi("Microsoft Edge 在线语音","Microsoft Edge online speech");
  return bi("<p>最近播放 · ","<p>Last played · ")+esc(recording.locale||'')+bi(" · 免费在线发音</p><p>服务商："," · Free online speech</p><p>Provider: ")+provider+bi("</p><p>由服务商在线生成，设备只接收并缓存音频，不调用付费 AI。</p><p class=\"hint\">这是在线生成的音频，不属于词典的开放录音；使用条件以服务商说明为准。</p>","</p><p>Generated online by the provider; your device receives and caches audio without calling paid AI.</p><p class=\"hint\">This audio is generated online and is not an openly licensed dictionary recording. The provider’s terms apply.</p>");
 }
 const source=recordingLink(recording.sourceUrl,bi("查看录音来源","View recording source"));
 const licenseUrl=recording.licenseUrl||(/^https?:\/\//i.test(recording.license||'')?recording.license:recording.sourceUrl);
 const license=recordingLink(licenseUrl,recording.license||bi("许可请见来源页面","See the source page for licensing"));
 return bi("<p>最近播放 · ","<p>Last played · ")+esc(recording.locale||'')+' · '+source+bi("</p><p>作者 / 署名：","</p><p>Author / Attribution: ")+esc(recording.attribution||bi("请见来源页面","See the source page"))+bi("</p><p>许可：","</p><p>License: ")+license+'</p>';
}
function renderRecordingAttribution(){const el=$('recording-attribution');if(el)el.innerHTML=recordingAttributionHTML();}
function speechSettingsHTML(){
 return bi("<section class=\"settings-section\"><h3>读音来源</h3><p id=\"service-description\">","<section class=\"settings-section\"><h3>Audio sources</h3><p id=\"service-description\">")+esc(recordingServiceDescription())+'</p><p id="recording-count">'+esc(recordingCounts())+bi("</p><p>优先播放内置及已缓存的词典录音，其他词条按需查找 Wiktionary / Wikimedia Commons 的现成录音。保留五套英语词库，录音覆盖按实际收录统计；也可导入自己的单词进行匹配。</p><label class=\"soft-button\"><input id=\"free-fallback\" class=\"switch\" type=\"checkbox\"","</p><p>Bundled and cached dictionary recordings come first. Other words are looked up on Wiktionary / Wikimedia Commons for existing recordings. All five English libraries are retained; recording coverage reflects what is available. Imported words can be matched too.</p><label class=\"soft-button\"><input id=\"free-fallback\" class=\"switch\" type=\"checkbox\"")+(state.settings.freeFallback!==false?' checked':'')+bi("><span>缺少录音时使用免费在线发音</span></label><p>开启后，词典没有对应录音或暂时无法访问时，由 Microsoft Edge 免费在线语音按所选语言和口音补齐并缓存。设备只接收音频，不运行语音模型，不调用付费 AI。</p><p>关闭后仅使用现成词典录音；未收录时停在当前单词并提醒。所有来源都不可用时会停止播放，保留当前进度。</p><button class=\"soft-button\" id=\"reload-recordings\">重新读取目录</button> <button class=\"soft-button\" id=\"preview-recording\">播放当前词条</button><p class=\"hint\">首次查找或生成新读音需要联网；离线时可播放内置及已经缓存的音频。</p></section><section class=\"settings-section\"><h3>来源与使用说明</h3><div id=\"recording-attribution\">","><span>Use free online speech when recordings are missing</span></label><p>When enabled, missing or temporarily unavailable recordings are supplemented by Microsoft Edge free online speech fills gaps in the selected language and accent, then caches the result. Your device receives audio without running a speech model or calling paid AI.</p><p>When off, only existing dictionary recordings are used. Missing or unavailable audio stops playback at the current word and keeps your progress.</p><button class=\"soft-button\" id=\"reload-recordings\">Reload recording index</button> <button class=\"soft-button\" id=\"preview-recording\">Play current word</button><p class=\"hint\">Finding or generating new audio requires a connection. Bundled and cached audio remains available offline.</p></section><section class=\"settings-section\"><h3>Sources and usage</h3><div id=\"recording-attribution\">")+recordingAttributionHTML()+'</div></section>';
}
function changeFreeFallback(event){
 pause();state.settings.freeFallback=event.target.checked;persist();recordingErrorContext=null;recordingCaptionContext='';refreshServiceStatus();
}
async function initializeRecordings(report=false){
 try{await voice.initialize();}catch(e){voice.dictionaryReady=false;voice.service={...voice.service,available:false,reason:translateUIMessage(e.message)};if(report)toast(translateUIMessage(e.message));}
 refreshServiceStatus();
}
async function reloadRecordings(){
 const button=$('reload-recordings');button.disabled=true;button.textContent=bi("正在读取…","Loading…");pause();
 try{await initializeRecordings(true);}finally{button.disabled=false;button.textContent=bi("重新读取目录","Reload recording index");}
}

function renderSettings(){const s=state.settings;$('language').value=s.language;$('speed').value=s.speed;$('speed-value').textContent=s.speed+'×';$('repeat-count').value=s.repeat;$('repeat-value').textContent=bi(s.repeat+' 次',s.repeat===1?'1 time':s.repeat+' times');$('interval').value=s.interval;$('interval-value').textContent=s.interval+bi(" 秒"," s");$('show-meaning').checked=s.showMeaning;$('autoplay-folder').checked=s.autoFolder;$('motion-toggle').checked=s.motion;document.body.classList.toggle('motion-off',!s.motion);$('accent-controls').hidden=s.language!=='en';$('language-voice-hint').hidden=s.language==='en';$('language-voice-hint').textContent=LANGUAGES[s.language].native+' · '+languageName(s.language)+bi("语音"," voice");$('accent-hint').textContent=s.language==='en'?'ACCENT':'LANGUAGE';document.querySelectorAll('[data-accent]').forEach(b=>{b.classList.toggle('selected',b.dataset.accent===s.accent);b.setAttribute('aria-pressed',String(b.dataset.accent===s.accent));});$('input-language').textContent=languageName(s.language);renderVoiceSettings();}
function render(){renderSettings();renderLibraryTree();renderWord();renderWordList();}
function pause(status=bi("已暂停","Paused")){playToken++;playing=false;voice.stop();wordTransition.cancel();setStatus(status);if(/^(正在|Finding |Getting |Loading |Preparing )/.test($('audio-source').textContent))$('audio-source').textContent=bi("读音来源 · ","Audio source · ")+status;const ref=queue[queueIndex];if(ref&&library(ref.libraryId)){state.positions[ref.libraryId]=ref.index;persist();}renderPlayback();}
function hideSpellingAnswer(){clearTimeout(revealTimer);revealTimer=null;$('spelling-answer').hidden=true;}
function resetAnswer(){
 passed=false;spellingAttempt=null;spellingComposing=false;hideSpellingAnswer();
 $('spelling-input').value='';$('spelling-input').classList.remove('correct','incorrect');$('spelling-input').removeAttribute('aria-invalid');
 $('spelling-feedback').textContent='';$('spelling-feedback').className='';
}
function renderSpellingWord(w,language){
 const heading=$('current-word'),spelling=mode==='spell'&&!!w;
 heading.lang=language;heading.classList.toggle('spelling-display',spelling);
 heading.classList.toggle('spelling-correct',spelling&&spellingAttempt?.correct===true);
 heading.classList.toggle('spelling-wrong',spelling&&spellingAttempt?.correct===false);
 const answer=spellingAttempt?.answer??$('spelling-input').value;
 const length=Math.max(spellingCharacters(w?.word||'',language).length,spelling?spellingCharacters(answer,language).length:0);
 heading.classList.toggle('long-word',length>(spelling?10:18)||/\s/.test(w?.word||''));
 if(!spelling){heading.textContent=w?.word||bi("准备出发","Ready to explore");heading.removeAttribute('aria-label');return;}
 const slots=spellingAttempt?.slots||spellingSlots(w.word,answer,language);
 heading.style.setProperty('--spell-length',String(slots.length));
 heading.setAttribute('aria-label',bi("拼写：","Spelling: ")+slots.map(slot=>slot.char|| (slot.gap?bi("空格","Space"):bi("空位","blank"))).join(' '));
 heading.innerHTML=slots.map(slot=>{
  const classes=['spell-slot',slot.char?'is-filled':'is-empty','is-'+slot.state];
  if(slot.gap)classes.push('spell-gap');if(slot.extra)classes.push('is-extra');
  const char=slot.char===' '&&!slot.gap?'␣':slot.char;
  return '<span aria-hidden="true" class="'+[...new Set(classes)].join(' ')+'">'+esc(char)+'</span>';
 }).join('');
}
function updateSpellingInput(){
 if(passed)return;
 spellingAttempt=null;hideSpellingAnswer();$('spelling-feedback').textContent='';$('spelling-feedback').className='';
 $('spelling-input').classList.remove('correct','incorrect');$('spelling-input').removeAttribute('aria-invalid');
 renderSpellingWord(current(),current()?.language||state.settings.language);
}
function selectLibrary(id,{autoplay=false,index,folderIds=null}={}){pause(bi("准备就绪","Ready"));test=null;const lib=library(id);if(!lib)return;state.activeLibrary=id;state.settings.language=lib.language;queue=buildQueue(state.libraries,folderIds||[id]);if(state.settings.shuffle)queue=shuffled(queue);const saved=index??Number(state.positions[id]||0);queueIndex=Math.max(0,queue.findIndex(r=>r.libraryId===id&&r.index===saved));historySession=null;listLimit=80;resetAnswer();render();persist();if(autoplay&&queue.length&&mode==='listen')startPlayback();else if(mode==='spell'&&queue.length)speakOnce();}
function recordHistory(){const w=current(),ref=queue[queueIndex];if(!w||!ref)return;let entry=state.history.find(h=>h.id===historySession);if(!entry){entry={id:uid(),libraryId:ref.libraryId,libraryName:library(ref.libraryId).name,language:w.language};state.history.unshift(entry);historySession=entry.id;}Object.assign(entry,{libraryId:ref.libraryId,libraryName:library(ref.libraryId).name,word:w.word,index:ref.index,at:Date.now(),mode,queueLibraryIds:[...new Set(queue.map(r=>r.libraryId))]});state.history=state.history.slice(0,200);$('history-count').textContent=state.history.length;persist();}
function recordingPlaybackError(error){
 const status=error.code==='missing_recording'?bi("查不到词典录音","Dictionary recording not found"):['catalog_load_failed','catalog_invalid'].includes(error.code)?bi("录音目录不可用","Recording index unavailable"):bi("读音加载失败","Audio could not be loaded");
 recordingErrorContext=recordingContext();recordingCaptionContext=recordingErrorContext;
 pause(status);rawAudioMessage=error.message||status;$('audio-source').textContent=translateUIMessage(rawAudioMessage);toast(rawAudioMessage);
}
async function speakOnce(accent=state.settings.accent){
 pause(bi("正在准备录音…","Preparing audio…"));const w=current();if(!w)return;const token=playToken;playing=true;renderPlayback();
 try{
  const accents=w.language==='en'&&accent==='both'?['uk','us']:[accent];
  for(const a of accents){
   if(token!==playToken)return;
   const finished=await voice.speak(w,a,state.settings);
   if(token!==playToken)return;
   if(!finished){pause(bi("播放已暂停","Playback paused"));return;}
  }
  recordHistory();renderRecordingAttribution();setStatus(bi("准备就绪","Ready"));
 }catch(e){if(token===playToken)recordingPlaybackError(e);}
 finally{if(token===playToken){playing=false;renderPlayback();}}
}
async function startPlayback(){
 if(mode==='spell'){await speakOnce();return;}
 if(!queue.length)return;
  pause();const token=playToken;playing=true;setStatus(bi("正在准备录音…","Preparing audio…"));renderPlayback();
 try{
  while(playing&&token===playToken){
   const w=current();if(!w)break;renderWord();
   for(let repetition=0;repetition<state.settings.repeat;repetition++){
    const accents=w.language==='en'&&state.settings.accent==='both'?['uk','us']:[state.settings.accent];
    for(const accent of accents){
     if(token!==playToken)return;
     const playback=voice.speak(w,accent,state.settings);
     if(repetition===0&&accent===accents[0]){
      const upcoming=queue.slice(queueIndex+1,queueIndex+4).map(ref=>library(ref.libraryId)?.words[ref.index]).filter(Boolean);
      // Prepare the current second accent first, then up to three upcoming words.
      if(accents.length>1)voice.prefetch(w,'us',state.settings);
      voice.prefetchUpcoming(upcoming,state.settings.accent,state.settings);
     }
     const finished=await playback;if(token!==playToken)return;if(!finished){pause(bi("播放已暂停","Playback paused"));return;}recordHistory();renderRecordingAttribution();
    }
    if(repetition<state.settings.repeat-1)await new Promise(r=>setTimeout(r,state.settings.interval*1000));
   }
   if(token!==playToken)return;
   await new Promise(r=>setTimeout(r,state.settings.interval*1000));if(token!==playToken)return;
   let nextIndex;if(queueIndex+1<queue.length)nextIndex=queueIndex+1;
   else if(state.settings.loop)nextIndex=0;
   else{pause(bi("本轮播放完成","Playback complete"));render();return;}
   await wordTransition.leave();if(token!==playToken)return;
   queueIndex=nextIndex;renderWord();await wordTransition.enter();if(token!==playToken)return;
   renderWordList();renderLibraryTree();
  }
  }catch(e){if(token===playToken)recordingPlaybackError(e);}
}
async function step(delta){if(mode==='spell'&&delta>0&&!passed&&!test)return;if(test){if(delta>0&&passed)nextTest();return;}const wasPlaying=playing;pause(bi("准备就绪","Ready"));const token=playToken;await wordTransition.leave();if(token!==playToken)return;if(delta>0&&queueIndex===queue.length-1&&state.settings.shuffle){queue=shuffled(queue);queueIndex=0;}else queueIndex=(queueIndex+delta+queue.length)%queue.length||0;resetAnswer();render();persist();await wordTransition.enter();if(token!==playToken)return;if(wasPlaying&&mode==='listen')startPlayback();else if(mode==='spell'){$('spelling-input').focus();speakOnce();}}
function switchMode(next){pause(bi("准备就绪","Ready"));if(test){test=null;queue=buildQueue(state.libraries,[state.activeLibrary]);queueIndex=0;}mode=next;document.body.classList.toggle('spell-mode',mode==='spell');$('mode-listen').classList.toggle('selected',mode==='listen');$('mode-spell').classList.toggle('selected',mode==='spell');$('mode-listen').setAttribute('aria-pressed',String(mode==='listen'));$('mode-spell').setAttribute('aria-pressed',String(mode==='spell'));$('brand-title').textContent=mode==='spell'?'星际盲拼 · 单词侦探':'星际单词播放器';document.title=$('brand-title').textContent;$('main-heading').textContent=mode==='spell'?bi("听见单词，拼出你的星空。","Hear a word. Spell your way through the stars."):bi("让每一个单词，都留下回响。","Let every word leave an echo.");$('shortcut-hint').textContent=mode==='spell'?bi("Tab / Alt + R 再读 · Enter 检查 / 继续","Tab / Alt + R Replay · Enter Check / Continue"):bi("空格 播放 / 暂停 · ← → 切换单词","Space Play / Pause · ← → Switch words");$('spell-tools').hidden=mode!=='spell';resetAnswer();render();if(mode==='spell'&&current()){$('spelling-input').focus();speakOnce();}}
function openModal(title,html){$('modal-title').textContent=title;$('modal-content').innerHTML=html;$('modal').showModal();icons($('modal'));}
function closeModal(){$('modal').close();}
function confirmAction(title,message,action){openModal(title,`<p>${esc(message)}${bi("</p><div class=\"modal-actions\"><button class=\"soft-button\" id=\"cancel-action\">取消</button><button class=\"primary\" id=\"confirm-action\">确认</button></div>","</p><div class=\"modal-actions\"><button class=\"soft-button\" id=\"cancel-action\">Cancel</button><button class=\"primary\" id=\"confirm-action\">Confirm</button></div>")}`);$('cancel-action').onclick=closeModal;$('confirm-action').onclick=()=>{closeModal();action();};}
function folderOptions(selected){return `${bi("<option value=\"\">我的词库</option>","<option value=\"\">My libraries</option>")}`+state.folders.map(f=>`<option value="${esc(f.id)}" ${f.id===selected?'selected':''}>${esc(f.name)}</option>`).join('');}
function languageOptions(selected){return Object.entries(LANGUAGES).map(([id,l])=>`<option value="${id}" ${id===selected?'selected':''}>${esc(languageChoice(id))}</option>`).join('');}
function editLibrary(id){const lib=id?library(id):null;openModal(lib?bi("管理词库","Manage library"):bi("新建错词本","New mistake library"),`${bi("<form id=\"library-form\"><label class=\"field\">词库名称<input id=\"lib-name\" required maxlength=\"80\" value=\"","<form id=\"library-form\"><label class=\"field\">Library name<input id=\"lib-name\" required maxlength=\"80\" value=\"")}${esc(lib?.name||'')}${bi("\" placeholder=\"为这片词海取个名字\"></label><label class=\"field\">学习语言<select id=\"lib-language\" ","\" placeholder=\"Name this collection of words\"></label><label class=\"field\">Learning language<select id=\"lib-language\" ")}${lib?.words.length?'disabled':''}>${languageOptions(lib?.language||state.settings.language)}${bi("</select></label><label class=\"field\">所属文件夹<select id=\"lib-folder\">","</select></label><label class=\"field\">Folder<select id=\"lib-folder\">")}${folderOptions(lib?.folderId)}</select></label><div class="modal-actions">${lib?bi("<button type=\"button\" class=\"text-button danger\" id=\"delete-library\">删除词库</button>","<button type=\"button\" class=\"text-button danger\" id=\"delete-library\">Delete library</button>"):''}${bi("<button class=\"primary\" type=\"submit\">保存词库</button></div></form>","<button class=\"primary\" type=\"submit\">Save library</button></div></form>")}`);$('library-form').onsubmit=e=>{e.preventDefault();const name=$('lib-name').value.trim();if(!name)return;const language=$('lib-language').value,folderId=$('lib-folder').value||null;if(state.libraries.some(l=>l.id!==id&&l.name===name&&l.folderId===folderId&&l.language===language)){toast(bi("同一文件夹内已有同名词库","A library with this name already exists in this folder."));return;}let targetId=id;if(lib)Object.assign(lib,{name,folderId});else{targetId=uid();state.libraries.push({id:targetId,name,folderId,language,words:[],builtin:false});}closeModal();selectLibrary(targetId);toast(bi("词库已保存","Library saved"));};if(lib)$('delete-library').onclick=()=>confirmAction(bi("删除词库","Delete library"),`${bi("删除“","Delete “")}${lib.name}${bi("”及其单词？此操作不删除电脑中的导出备份。","” and its words? Exported backups on your computer will remain.")}`,()=>{pause();state.libraries=state.libraries.filter(l=>l.id!==id);ensureTemporary(state.settings.language);selectLibrary(state.libraries.find(l=>l.language===state.settings.language&&!l.builtin).id);persist();});}
function editFolder(id){const folder=state.folders.find(f=>f.id===id);openModal(folder?bi("管理文件夹","Manage folder"):bi("新建文件夹","New folder"),`${bi("<form id=\"folder-form\"><label class=\"field\">文件夹名称<input id=\"folder-name\" required maxlength=\"60\" value=\"","<form id=\"folder-form\"><label class=\"field\">Folder name<input id=\"folder-name\" required maxlength=\"60\" value=\"")}${esc(folder?.name||'')}${bi("\" placeholder=\"例如：每日听读\"></label><p class=\"hint\">将词库移入文件夹后，打开文件夹即可连续播放其中的单词。自动播放可在播放控制中关闭。</p><div class=\"modal-actions\">","\" placeholder=\"For example: Daily listening\"></label><p class=\"hint\">Move libraries into a folder to listen to them in sequence. Folder autoplay can be turned off in Playback controls.</p><div class=\"modal-actions\">")}${folder?bi("<button type=\"button\" class=\"text-button danger\" id=\"delete-folder\">删除文件夹</button>","<button type=\"button\" class=\"text-button danger\" id=\"delete-folder\">Delete folder</button>"):''}${bi("<button class=\"primary\">保存文件夹</button></div></form>","<button class=\"primary\">Save folder</button></div></form>")}`);$('folder-form').onsubmit=e=>{e.preventDefault();const name=$('folder-name').value.trim();if(!name)return;if(state.folders.some(f=>f.id!==id&&f.name===name)){toast(bi("已有同名文件夹","A folder with this name already exists."));return;}if(folder)folder.name=name;else state.folders.push({id:uid(),name});closeModal();renderLibraryTree();persist();};if(folder)$('delete-folder').onclick=()=>confirmAction(bi("删除文件夹","Delete folder"),bi("文件夹中的词库会移回“我的词库”，单词不会丢失。","Libraries in this folder will return to My libraries. Your words will be kept."),()=>{state.folders=state.folders.filter(f=>f.id!==id);state.libraries.forEach(l=>{if(l.folderId===id)l.folderId=null;});renderLibraryTree();persist();});}
function ensureTemporary(language){let lib=state.libraries.find(l=>l.id==='temp-'+language);if(!lib){lib={id:'temp-'+language,name:'临时词库',language,folderId:null,words:[samples(language)[0]],builtin:false};state.libraries.push(lib);}return lib;}
function editWord(index){const lib=library(),w=lib.words[index];if(lib.builtin)return;openModal(bi("编辑单词","Edit word"),`${bi("<form id=\"word-form\"><label class=\"field\">单词<input id=\"edit-word\" required maxlength=\"200\" value=\"","<form id=\"word-form\"><label class=\"field\">Word<input id=\"edit-word\" required maxlength=\"200\" value=\"")}${esc(w.word)}${bi("\"></label><label class=\"field\">词性<input id=\"edit-pos\" value=\"","\"></label><label class=\"field\">Part of speech<input id=\"edit-pos\" value=\"")}${esc(w.pos)}${bi("\"></label><label class=\"field\">中文含义<input id=\"edit-meaning\" value=\"","\"></label><label class=\"field\">Chinese meaning<input id=\"edit-meaning\" value=\"")}${esc(w.meaning)}${bi("\"></label><label class=\"field\">音标 / 假名 / 罗马音<input id=\"edit-phonetic\" value=\"","\"></label><label class=\"field\">Pronunciation / Kana / Romanization<input id=\"edit-phonetic\" value=\"")}${esc(w.phonetic)}${bi("\"></label><div class=\"modal-actions\"><button type=\"button\" id=\"delete-word\" class=\"text-button danger\">删除单词</button><button class=\"primary\">保存</button></div></form>","\"></label><div class=\"modal-actions\"><button type=\"button\" id=\"delete-word\" class=\"text-button danger\">Delete word</button><button class=\"primary\">Save</button></div></form>")}`);$('word-form').onsubmit=e=>{e.preventDefault();const word=$('edit-word').value.trim();if(!word)return;const changed=word!==w.word;Object.assign(w,{word,pos:$('edit-pos').value,meaning:$('edit-meaning').value,phonetic:$('edit-phonetic').value,...changed?{audio:{},definition:''}:{}});closeModal();render();persist();};$('delete-word').onclick=()=>confirmAction(bi("删除单词","Delete word"),`${bi("从当前词库删除“","Remove “")}${w.word}${bi("”？","”?")}`,()=>{lib.words.splice(index,1);selectLibrary(lib.id);});}
async function exportLibrary(){const lib=library();if(!lib)return;try{await storage.saveFile(lib.name+'.txt',toCSV(lib.words),'text/plain;charset=utf-8');toast(storage.currentDirectory()?bi("已保存到统一目录","Saved to your folder"):bi("已导出当前词库","Library exported"));}catch(e){toast(translateUIMessage(e.message));}}
function addErrors(){const words=(library()?.words||[]).filter(w=>w.errorCount>0);if(!words.length){toast(bi("当前没有错误单词","No mistakes in this library"));return;}openModal(bi("添加错误到...","Add mistakes to..."),`${bi("<label class=\"field\">选择目标错词本<select id=\"error-target\">","<label class=\"field\">Choose a mistake library<select id=\"error-target\">")}${state.libraries.filter(l=>!l.builtin&&l.language===state.settings.language).map(l=>`<option value="${esc(l.id)}">${esc(l.name)}</option>`).join('')}${bi("</select></label><div class=\"modal-actions\"><button id=\"save-errors\" class=\"primary\">添加 ","</select></label><div class=\"modal-actions\"><button id=\"save-errors\" class=\"primary\">Add ")}${words.length}${bi(" 个错词</button></div>"," mistakes</button></div>")}`);$('save-errors').onclick=()=>{const target=library($('error-target').value);target.words=uniqueWords([...target.words,...structuredClone(words)]);persist();render();closeModal();toast(bi("错误单词已添加","Mistakes added"));};}
function favorite(){const w=current();if(!w)return;let lib=state.libraries.find(l=>l.name==='我的收藏'&&l.language===w.language&&!l.builtin);if(!lib){lib={id:uid(),name:'我的收藏',language:w.language,words:[],builtin:false,folderId:null};state.libraries.push(lib);}lib.words=uniqueWords([...lib.words,structuredClone(w)]);persist();renderLibraryTree();toast(bi("已收藏到“我的收藏”","Saved to “我的收藏”"));}
async function importWords(words,name){if(!words.length){toast(bi("没有可导入的单词","No words to import"));return;}if(querying){toast(bi("正在查询，请稍候","Looking up words. Please wait."));return;}querying=true;$('query-words').disabled=true;$('upload-words').disabled=true;$('query-progress').textContent=`${bi("正在查询 0 / ","Looking up 0 / ")}${words.length}…`;const language=words[0].language;try{const enriched=await enrichWords(words,(done,total)=>{$('query-progress').textContent=`${bi("正在查询 ","Looking up ")}${done} / ${total}…`;});let lib=library();if(!lib||lib.builtin||lib.language!==language||name){lib={id:uid(),name:name||`${bi("单词集 ","Word collection ")}${new Date().toLocaleDateString('zh-CN')} ${new Date().toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit'})}`,language,words:[],folderId:null,builtin:false};state.libraries.push(lib);}lib.words=uniqueWords([...lib.words,...enriched]);selectLibrary(lib.id);const missing=enriched.filter(w=>!w.meaning).length;$('query-progress').textContent=`${bi("已加入 ","Added ")}${enriched.length}${bi(" 个单词"," words")}${missing?`${bi("，",", ")}${missing}${bi(" 个释义暂缺，可手动编辑补充"," definitions missing; edit them in the word list")}`:''}${bi("。",".")}`;toast(bi("单词已加入词库","Words added to the library"));}catch(e){toast(bi("查询失败：","Lookup failed: ")+translateUIMessage(e.message));$('query-progress').textContent=bi("查询未完成，输入内容仍保留，可重新尝试。","The lookup did not finish. Your input is preserved; you can try again.");}finally{querying=false;$('query-words').disabled=false;$('upload-words').disabled=false;}}
function showHistory(){openModal(bi("播放历史","Listening history"),`${bi("<p class=\"hint\" style=\"margin-bottom:15px\">记录最近 200 次学习。点击继续，从上次的单词出发。</p><div id=\"history-entries\">","<p class=\"hint\" style=\"margin-bottom:15px\">Your latest 200 learning sessions. Resume from the last word.</p><div id=\"history-entries\">")}${state.history.map(h=>`<div class="history-row"><div><strong>${esc(h.word)} <small>· ${esc(languageName(h.language||'en'))}</small></strong><small>${esc(h.libraryName)} · ${new Date(h.at).toLocaleString(getUILanguage()==='en'?'en-GB':'zh-CN',{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'})}</small></div><button class="soft-button" data-resume="${esc(h.id)}">${icon('play')}${bi(" 继续</button></div>"," Continue</button></div>")}`).join('')||bi("<p class=\"empty-state\">星际旅程从第一次播放开始。<br>你的听读记录会自动保存在这里。</p>","<p class=\"empty-state\">Your journey begins with the first word.<br>Your listening sessions will appear here automatically.</p>")}${bi("</div><div class=\"modal-actions\"><button id=\"clear-history\" class=\"text-button danger\">清空播放历史</button></div>","</div><div class=\"modal-actions\"><button id=\"clear-history\" class=\"text-button danger\">Clear listening history</button></div>")}`);$('modal-content').onclick=e=>{const b=e.target.closest('[data-resume]');if(b){const h=state.history.find(h=>h.id===b.dataset.resume),lib=library(h.libraryId);if(!lib){toast(bi("原词库已删除，无法继续","The original library was deleted and cannot be resumed."));return;}closeModal();if(mode!=='listen')switchMode('listen');selectLibrary(lib.id,{index:h.index,folderIds:h.queueLibraryIds?.filter(id=>library(id)),autoplay:true});}};$('clear-history').onclick=()=>confirmAction(bi("清空播放历史","Clear listening history"),bi("仅删除播放历史，词库与错词记录会保留。","Only listening history will be removed. Libraries and mistake records will be kept."),()=>{state.history=[];historySession=null;persist();renderLibraryTree();toast(bi("历史已清空","History cleared"));});}
function showStorage(){const dir=storage.currentDirectory();openModal(bi("保存与服务设置","Storage and services"),`${bi("<section class=\"settings-section\"><h3>统一保存路径</h3><div class=\"path-label\">","<section class=\"settings-section\"><h3>Save location</h3><div class=\"path-label\">")}${dir?esc(dir.name):bi("尚未选择 · 当前保存在浏览器","No folder selected · Currently saved in this browser")}${bi("</div><p>选择目录后，自建词库、文件夹、错词记录和播放历史会自动保存到其中的“星际单词学习”文件夹。刷新后保留目录设置；权限失效时点击重新连接。</p><button class=\"primary\" id=\"choose-directory\">","</div><p>Your libraries, folders, mistakes and listening history are saved in the “星际单词学习” subfolder. The chosen folder is remembered; reconnect if permission expires.</p><button class=\"primary\" id=\"choose-directory\">")}${icon('folder')} ${dir?bi("更改保存目录","Change save folder"):bi("选择保存目录","Choose save folder")}</button>${dir?bi("<button class=\"soft-button\" id=\"reconnect-directory\">重新连接并保存</button>","<button class=\"soft-button\" id=\"reconnect-directory\">Reconnect and save</button>"):''}${bi("<p class=\"hint\">指定目录需要桌面 Chrome / Edge 等支持的浏览器；其他浏览器可使用完整备份。</p></section><section class=\"settings-section\"><h3>备份与迁移</h3><p>完整备份包含所有词库、文件夹、播放历史和设置。旧站的 TXT / CSV 单词文件可在“输入单词列表”中导入；旧站数据不会自动跨域迁移。</p><button class=\"soft-button\" id=\"backup-all\">导出完整备份</button> <button class=\"soft-button\" id=\"restore-backup\">导入完整备份</button><input hidden type=\"file\" id=\"backup-file\" accept=\".json\"></section>","<p class=\"hint\">Choosing a folder requires desktop Chrome / Edge or another compatible desktop browser. Other browsers can use full backups.</p></section><section class=\"settings-section\"><h3>Backup and transfer</h3><p>A full backup includes libraries, folders, history and settings. Previous-site TXT / CSV word files can be imported under Add words. Data does not automatically transfer from the previous website.</p><button class=\"soft-button\" id=\"backup-all\">Export full backup</button> <button class=\"soft-button\" id=\"restore-backup\">Import full backup</button><input hidden type=\"file\" id=\"backup-file\" accept=\".json\"></section>")}${speechSettingsHTML()}${bi("<section class=\"settings-section\"><h3>当前词库</h3><button class=\"text-button danger\" id=\"clear-library\" ","<section class=\"settings-section\"><h3>Current library</h3><button class=\"text-button danger\" id=\"clear-library\" ")}${library()?.builtin?'disabled':''}${bi(">清除当前学习单词词库</button><p>内置语料库只读，自建词库可编辑、整理与导出。</p></section>",">Clear this learning library</button><p>Built-in libraries are read-only. Your own libraries can be edited, organized and exported.</p></section>")}`);$('free-fallback').onchange=changeFreeFallback;$('reload-recordings').onclick=reloadRecordings;$('preview-recording').onclick=()=>speakOnce();$('choose-directory').onclick=async()=>{try{await connectLearningDirectory(false);$('storage-status').textContent=bi("统一目录已连接","Save folder connected");$('storage-summary').textContent=storage.currentDirectory().name;closeModal();toast(bi("统一保存目录已设置并完成首次备份","Save folder connected and first backup created"));}catch(e){if(e.name!=='AbortError')toast(translateUIMessage(e.message));}};if(dir)$('reconnect-directory').onclick=async()=>{try{await connectLearningDirectory(true);closeModal();toast(bi("已连接并保存到统一目录","Connected and saved to your folder"));}catch(e){toast(translateUIMessage(e.message));}};$('backup-all').onclick=async()=>{try{await storage.saveFile('星际单词完整备份-'+new Date().toISOString().slice(0,10)+'.json',JSON.stringify(state,null,2));toast(bi("完整备份已导出","Full backup exported"));}catch(e){toast(translateUIMessage(e.message));}};$('restore-backup').onclick=()=>$('backup-file').click();$('backup-file').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{const imported=sanitizeState(JSON.parse(await file.text()));confirmAction(bi("导入完整备份","Import full backup"),`${bi("这将替换当前学习数据，载入 ","This replaces current learning data with ")}${imported.libraries.length}${bi(" 个词库和 "," libraries and ")}${imported.folders.length}${bi(" 个文件夹。建议先导出当前备份。"," folders. Export your current data first if needed.")}`,()=>{pause();state=imported;state.settings.voice='recorded';state.settings.freeFallback=state.settings.freeFallback!==false;selectLibrary(state.activeLibrary);skins?.refresh();journey?.refresh();persist();toast(bi("备份已恢复","Backup restored"));});}catch(e){toast(bi("备份无效：","Invalid backup: ")+translateUIMessage(e.message));}};$('clear-library').onclick=()=>{const lib=library();if(lib.builtin)return;confirmAction(bi("清除当前学习单词词库","Clear this learning library"),`${bi("清除“","Clear “")}${lib.name}${bi("”中的所有单词？","” and all its words?")}`,()=>{lib.words=[];selectLibrary(lib.id);closeModal();});};}
function checkSpelling(event){
 event.preventDefault();if(spellingComposing||event.isComposing)return;
 if(passed){step(1);return;}const w=current();if(!w)return;
 const result=evaluateSpelling($('spelling-input').value,w.word,w.language);
 if(result.empty&&!test){toast(bi("请先输入答案","Enter an answer first"));return;}
 hideSpellingAnswer();spellingAttempt=result;
 const feedback=$('spelling-feedback'),input=$('spelling-input');
 feedback.className=result.correct?'correct':'incorrect';
 input.classList.toggle('correct',result.correct);input.classList.toggle('incorrect',!result.correct);
 input.setAttribute('aria-invalid',String(!result.correct));
 if(result.correct){passed=true;feedback.textContent=test?bi("回答正确 · Enter 继续","Correct · Enter Continue"):bi("拼写正确 · Enter 继续","Correct spelling · Enter Continue");}
 else{w.errorCount=(w.errorCount||0)+1;feedback.textContent=result.empty?bi("已跳过 · 正确答案如下","Skipped · The correct answer is shown below"):test?bi("回答错误 · 橙红色标出错误位置","Incorrect · Orange-red marks show the errors"):bi("拼写错误 · 橙红色标出错误位置，请修改后重试","Not quite · Orange-red marks show what to correct. Try again.");}
 if(test){
  passed=true;test.answered++;w.testTotal=(w.testTotal||0)+1;
  if(result.correct){test.correct++;w.testCorrect=(w.testCorrect||0)+1;}
  feedback.innerHTML+=bi("<div class=\"test-progress\">第 ","<div class=\"test-progress\">Question ")+test.answered+' / '+queue.length+bi(" 题 · 正确 "," · Correct ")+test.correct+bi(" 题</div>","</div>");
 }
 $('spelling-answer').querySelector('.answer-word').textContent=w.word;$('spelling-answer').hidden=false;
 if(!result.correct&&!test)revealTimer=setTimeout(()=>{if(spellingAttempt===result&&current()===w)$('spelling-answer').hidden=true;revealTimer=null;},3000);
 renderWord();renderWordList();recordHistory();persist();
 if(result.correct&&!test)speakOnce();
}
function beginTest(){if(!(library()?.words.length)){toast(bi("当前词库为空，请先添加单词","This library is empty. Add some words first."));return;}pause();openModal(bi("测验模式","Test mode"),`${bi("<p>听读音后拼写，每题记录首次回答。测验中隐藏音标与释义。</p><label class=\"field\">测验词库<select id=\"test-library\">","<p>Listen and spell. Your first answer is scored; pronunciation guides and definitions are hidden during the test.</p><label class=\"field\">Test library<select id=\"test-library\">")}${state.libraries.filter(l=>l.language===state.settings.language&&l.words.length).map(l=>`<option value="${esc(l.id)}" ${l.id===state.activeLibrary?'selected':''}>${esc(l.name)}</option>`).join('')}${bi("<option value=\"all\">当前语言的全部词库</option></select></label><label class=\"field\">题量<input id=\"test-count\" type=\"number\" min=\"1\" max=\"100\" value=\"10\" required></label><div class=\"modal-actions\"><button class=\"primary\" id=\"start-test\">开始测验</button></div>","<option value=\"all\">All libraries in the current learning language</option></select></label><label class=\"field\">Questions<input id=\"test-count\" type=\"number\" min=\"1\" max=\"100\" value=\"10\" required></label><div class=\"modal-actions\"><button class=\"primary\" id=\"start-test\">Start test</button></div>")}`);$('start-test').onclick=()=>{const count=Number($('test-count').value);if(!Number.isInteger(count)||count<1||count>100){toast(bi("题量须为 1–100 的整数","Enter a whole number from 1 to 100."));return;}const choice=$('test-library').value;const pool=buildQueue(state.libraries,choice==='all'?state.libraries.filter(l=>l.language===state.settings.language).map(l=>l.id):[choice]);queue=shuffled(pool).slice(0,count);queueIndex=0;const originalLibrary=state.activeLibrary;switchMode('spell');pause();test={correct:0,answered:0,originalLibrary};resetAnswer();closeModal();render();setStatus(bi("测验进行中","Test in progress"));$('spelling-input').focus();speakOnce();};}
function finishTest(){
 const results={...test,total:queue.length};pause();test=null;
 openModal(bi("测验完成","Test complete"),`<div class="test-score"><strong>${results.answered?Math.round(results.correct/results.answered*100):0}${bi("%</strong><p>已作答 ","%</strong><p>Answered ")}${results.answered} / ${results.total}${bi(" 题，答对 "," questions; correct: ")}${results.correct}${bi(" 题</p><p class=\"hint\">正确率按已作答题目计算。错误单词已加入原词库的错词记录。</p></div><div class=\"modal-actions\"><button class=\"primary\" id=\"finish-test\">返回学习</button></div>"," questions</p><p class=\"hint\">Accuracy is based on answered questions. Mistakes are recorded in the original library.</p></div><div class=\"modal-actions\"><button class=\"primary\" id=\"finish-test\">Back to learning</button></div>")}`);
 $('finish-test').onclick=()=>{closeModal();selectLibrary(results.originalLibrary);};queue=buildQueue(state.libraries,[state.activeLibrary]);queueIndex=0;resetAnswer();render();
}
function nextTest(){if(queueIndex+1>=queue.length){finishTest();return;}queueIndex++;resetAnswer();render();$('spelling-input').focus();speakOnce();}
function refreshInterfaceLanguage(){
 const language=getUILanguage();document.documentElement.lang=language==='en'?'en':'zh-CN';document.documentElement.dataset.uiLanguage=language;document.body.classList.toggle('ui-en',language==='en');
 refreshStaticUI();state.settings.uiLanguage=language;
 const toggle=$('ui-language-toggle');if(toggle){toggle.dataset.language=language;toggle.setAttribute('aria-pressed',String(language==='en'));toggle.setAttribute('aria-label',bi('切换界面语言为英文','Switch interface language to Chinese'));toggle.title=bi('界面语言 · 与学习语言独立','Interface language · Separate from learning language');}
 for(const option of $('language').options)option.textContent=languageChoice(option.value);
 $('main-heading').textContent=mode==='spell'?bi('听见单词，拼出你的星空。','Hear a word. Spell your way through the stars.'):bi('让每一个单词，都留下回响。','Let every word leave an echo.');
 $('shortcut-hint').textContent=mode==='spell'?bi('Tab / Alt + R 再读 · Enter 检查 / 继续','Tab / Alt + R Replay · Enter Check / Continue'):bi('空格 播放 / 暂停 · ← → 切换单词','Space Play / Pause · ← → Switch words');
 $('mode-spell').setAttribute('aria-label',bi('星际盲拼','Spelling practice · 星际盲拼'));
 if(!workspaceLoading){
  render();refreshServiceStatus();setStatus(rawStatusMessage);
  if(rawAudioMessage&&recordingCaptionContext===recordingContext())$('audio-source').textContent=translateUIMessage(rawAudioMessage);
  if(spellingAttempt){const result=spellingAttempt,feedback=$('spelling-feedback');feedback.textContent=result.correct?(test?bi('回答正确 · Enter 继续','Correct · Enter Continue'):bi('拼写正确 · Enter 继续','Correct spelling · Enter Continue')):result.empty?bi('已跳过 · 正确答案如下','Skipped · The correct answer is shown below'):test?bi('回答错误 · 橙红色标出错误位置','Incorrect · Orange-red marks show the errors'):bi('拼写错误 · 橙红色标出错误位置，请修改后重试','Not quite · Orange-red marks show what to correct. Try again.');if(test)feedback.innerHTML+='<div class="test-progress">'+bi('第 ','Question ')+test.answered+' / '+queue.length+bi(' 题 · 正确 ',' · Correct ')+test.correct+'</div>';}
  $('storage-status').textContent=storage.currentDirectory()?bi('统一保存目录','Save folder'):accountUser?bi('个人空间','Personal space'):bi('本地存储','Local storage');
  $('storage-summary').textContent=translateUIMessage($('storage-summary').textContent);
  if(!$('toast').hidden)$('toast').textContent=translateUIMessage($('toast').textContent);
 }
 $('toggle-sidebar').setAttribute('aria-label',$('workspace').classList.contains('sidebar-collapsed')?bi('展开词库管理','Expand library manager'):bi('折叠词库管理','Collapse library manager'));
 $('toggle-focus').setAttribute('aria-label',document.body.classList.contains('focus-mode')?bi('退出沉浸模式','Exit immersive view'):bi('开启沉浸模式','Enter immersive view'));
 $('toggle-list').setAttribute('aria-label',$('word-list').hidden?bi('展开单词列表','Expand word list'):bi('折叠单词列表','Collapse word list'));
}
