function createStars(){
 const fragment=document.createDocumentFragment();let seed=27;const random=()=>{seed=(seed*16807)%2147483647;return(seed-1)/2147483646;};
 for(let i=0;i<190;i++){const star=document.createElement('i');star.className='star'+(i%6===0?' bright':'');const size=i%9===0?2.6:i%3===0?1.8:1.15;star.style.cssText='left:'+random()*100+'%;top:'+random()*100+'%;width:'+size+'px;height:'+size+'px;--duration:'+(3.5+random()*5)+'s;--delay:-'+random()*9+'s';fragment.append(star);}
 $('stars').append(fragment);
 function oneMeteor(){const rate=normalizeSceneryOptions(state.settings.scenery).meteors/100;if(!rate||state.settings.skin!=='star'||!state.settings.motion||document.hidden||document.body.classList.contains('journey-open')||matchMedia('(prefers-reduced-motion: reduce)').matches)return;const m=document.createElement('i');m.className='meteor';m.style.left=Math.random()*76+'%';m.style.top=Math.random()*48+'%';$('meteors').append(m);for(const animation of m.getAnimations())animation.updatePlaybackRate(rate);m.addEventListener('animationend',()=>m.remove(),{once:true});m.addEventListener('animationcancel',()=>m.remove(),{once:true});}
 function meteor(){const rate=normalizeSceneryOptions(state.settings.scenery).meteors/100;oneMeteor();if(rate&&Math.random()>.65)setTimeout(oneMeteor,900/Math.max(.1,rate));setTimeout(meteor,(10000+Math.random()*9000)/Math.max(.3,rate));}
 setTimeout(meteor,1800);
}

