$('language').onchange=e=>{pause();const lang=e.target.value;state.settings.language=lang;const lib=ensureTemporary(lang);selectLibrary(lib.id);toast(bi("已切换为","Learning language: ")+languageName(lang)+bi(" · 可为每个词库设置语言"," · Each library can use its own language"));};document.querySelectorAll('[data-accent]').forEach(b=>b.onclick=()=>{pause();state.settings.accent=b.dataset.accent;renderSettings();persist();});for(const[id,key]of[['speed','speed'],['repeat-count','repeat'],['interval','interval']])$(id).oninput=e=>{state.settings[key]=Number(e.target.value);renderSettings();persist();};for(const[id,key]of[['show-meaning','showMeaning'],['autoplay-folder','autoFolder'],['motion-toggle','motion']])$(id).onchange=e=>{state.settings[key]=e.target.checked;if(key==='motion'&&!state.settings.motion)wordTransition.cancel();renderSettings();renderWord();persist();};
$('library-tree').onclick=e=>{const lib=e.target.closest('[data-library]');if(lib){selectLibrary(lib.dataset.library);return;}const edit=e.target.closest('[data-edit-lib]');if(edit){editLibrary(edit.dataset.editLib);return;}const folderEdit=e.target.closest('[data-edit-folder]');if(folderEdit){editFolder(folderEdit.dataset.editFolder);return;}const fold=e.target.closest('[data-fold-folder]');if(fold){const id=fold.dataset.foldFolder;collapsedFolders.has(id)?collapsedFolders.delete(id):collapsedFolders.add(id);renderLibraryTree();return;}const section=e.target.closest('[data-section]');if(section){const id=section.dataset.section;collapsedFolders.has(id)?collapsedFolders.delete(id):collapsedFolders.add(id);renderLibraryTree();return;}const folder=e.target.closest('[data-folder]');if(folder){const id=folder.dataset.folder;if(collapsedFolders.has(id)){collapsedFolders.delete(id);renderLibraryTree();}const libs=state.libraries.filter(l=>l.folderId===id&&l.language===state.settings.language&&l.words.length);if(libs.length){selectLibrary(libs[0].id,{folderIds:libs.map(l=>l.id),index:0,autoplay:state.settings.autoFolder});}else{collapsedFolders.has(id)?collapsedFolders.delete(id):collapsedFolders.add(id);renderLibraryTree();toast(bi("将词库移入此文件夹后即可连续播放","Add libraries to this folder to play them in sequence"));}}};
$('word-list').onclick=e=>{if(test){toast(bi("请先完成或结束测验，再切换或编辑单词","Finish or end the test before switching or editing words."));return;}if(e.target.closest('#more-words')){listLimit+=80;renderWordList();return;}const edit=e.target.closest('[data-edit-word]');if(edit){editWord(Number(edit.dataset.editWord));return;}const b=e.target.closest('[data-word-index],[data-speak-index]');if(b){const lib=library();pause();const index=Number(b.dataset.wordIndex??b.dataset.speakIndex);queue=buildQueue(state.libraries,[lib.id]);queueIndex=index;resetAnswer();render();persist();if(b.dataset.speakIndex!==undefined||mode==='spell')speakOnce();}};$('word-search').oninput=()=>{listLimit=80;renderWordList();};$('library-search').oninput=renderLibraryTree;$('new-library').onclick=()=>editLibrary();$('new-folder').onclick=()=>editFolder();$('export-library').onclick=exportLibrary;$('export-list').onclick=exportLibrary;$('add-errors').onclick=addErrors;$('open-history').onclick=showHistory;$('open-settings').onclick=showStorage;$('storage-settings').onclick=showStorage;$('close-modal').onclick=closeModal;$('modal').addEventListener('close',()=>{$('modal-content').onclick=null;});$('modal').addEventListener('click',e=>{if(e.target===$('modal')){const rect=$('modal').getBoundingClientRect();if(e.clientX<rect.left||e.clientX>rect.right||e.clientY<rect.top||e.clientY>rect.bottom)closeModal();}});
$('toggle-list').onclick=()=>{const hidden=!$('word-list').hidden;$('word-list').hidden=hidden;$('list-tools').hidden=hidden;$('toggle-list').setAttribute('aria-expanded',String(!hidden));$('toggle-list').setAttribute('aria-label',hidden?bi("展开单词列表","Expand word list"):bi("折叠单词列表","Collapse word list"));};$('toggle-input').onclick=()=>{const hidden=!$('input-body').hidden;$('input-body').hidden=hidden;$('toggle-input').setAttribute('aria-expanded',String(!hidden));};$('load-samples').onclick=()=>{$('word-input').value=samples(state.settings.language).map(w=>`${w.word},${w.pos},${w.meaning.replaceAll(',','，')},${w.phonetic}`).join('\n');toast(bi("示例已填入，点击“查询单词信息”加入词库","Examples are ready. Choose Look up words to add them to the library."));};$('clear-input').onclick=()=>{$('word-input').value='';$('query-progress').textContent='';};$('query-words').onclick=()=>{try{const words=parseWords($('word-input').value,state.settings.language);importWords(words);}catch(e){toast(translateUIMessage(e.message));}};$('upload-words').onclick=()=>$('file-input').click();$('file-input').onchange=async e=>{const files=[...e.target.files];for(const file of files){if(file.size>5*1024*1024){toast(file.name+bi(" 超过 5 MB，请分批导入"," exceeds 5 MB, please import in smaller batches"));continue;}try{const words=parseWords(await file.text(),state.settings.language);await importWords(words,file.name.replace(/\.[^.]+$/,''));}catch(e){toast(bi("导入失败：","Import failed: ")+translateUIMessage(e.message));}}e.target.value='';};
$('spelling-form').onsubmit=checkSpelling;$('review-errors').onclick=()=>{const lib=library(),refs=buildQueue(state.libraries,[lib.id]).filter(r=>lib.words[r.index].errorCount>0);if(!refs.length){toast(bi("当前没有错词","No mistakes to review"));return;}pause();queue=state.settings.shuffle?shuffled(refs):refs;queueIndex=0;test=null;resetAnswer();render();toast(bi("开始复习当前错词","Reviewing current mistakes"));speakOnce();};$('reset-errors').onclick=()=>confirmAction(bi("重置当前词库错误","Reset library mistakes"),bi("将当前词库的错误计数归零？","Reset mistake counts for this library?"),()=>{library().words.forEach(w=>w.errorCount=0);persist();renderWordList();});$('test-mode').onclick=()=>{if(test)confirmAction(bi("结束测验","End test"),bi("结束本次测验并查看已作答题目的成绩？","End this test and view results for answered questions?"),finishTest);else beginTest();};
document.addEventListener('keydown',e=>{
 if(workspaceLoading||e.isComposing||e.keyCode===229||spellingComposing||document.querySelector('dialog[open]'))return;
 const active=document.activeElement,editing=/^(INPUT|TEXTAREA|SELECT)$/.test(active.tagName)||active.isContentEditable;
 if(active.closest?.('#ui-language-toggle')&&(e.code==='Space'||e.key==='Enter'))return;
 if(editing&&active.id!=='spelling-input')return;
 if(e.altKey&&e.key.toLowerCase()==='r'){e.preventDefault();speakOnce();return;}
 if(mode==='spell'&&e.key==='Enter'&&passed){e.preventDefault();step(1);return;}
 if(editing)return;
 if(e.code==='Space'){e.preventDefault();playing?pause():startPlayback();}
 if(e.key==='ArrowRight'){e.preventDefault();step(1);}if(e.key==='ArrowLeft'){e.preventDefault();step(-1);}
 if(e.key==='Escape')document.body.classList.remove('focus-mode');
});
matchMedia('(prefers-reduced-motion: reduce)').addEventListener('change',event=>{if(event.matches)wordTransition.cancel();});
document.addEventListener('visibilitychange',()=>{if(document.hidden)saveNow();else welcomeIfReady().catch(()=>{});});window.addEventListener('pagehide',()=>{voice.stop();saveNow();});window.addEventListener('offline',refreshServiceStatus);window.addEventListener('online',()=>{initializeRecordings();});
async function cachedWorkspace(){
 let databaseState=null,recovery=null;
 try{databaseState=await storage.get('state');}catch{}
 try{recovery=JSON.parse(localStorage.getItem(storage.recoveryKey()));}catch{}
 const saved=recovery&&(!databaseState||(recovery.modifiedAt||0)>=(databaseState.modifiedAt||0))?recovery:databaseState;
 if(!saved)return null;try{return sanitizeState(saved);}catch{toast(bi("学习缓存格式异常，请从自定义文件夹或备份恢复","The learning cache could not be read. Restore it from your folder or a backup."));return null;}
}
async function readConnectedDirectory(){
 if(!storage.currentDirectory())return false;
 if(!await storage.directoryReady()){$('storage-summary').textContent=bi("目录待授权 · 点击设置重新连接","Folder permission needed · Reconnect in Settings");return false;}
 const disk=await readStudyDirectory(storage.currentDirectory(),{language:state.settings.language,preferRoot:storage.usesSourceRoot()});
 if(disk.snapshot){
  const fromDisk=sanitizeState(disk.snapshot);
  // Daily visits are local session records; a disk library edit must not erase them.
  fromDisk.journey=normalizeJourney({days:[...(fromDisk.journey?.days||[]),...(state.journey?.days||[])],lastIntroDay:[fromDisk.journey?.lastIntroDay||'',state.journey?.lastIntroDay||''].sort().at(-1)});
  state=migrateLegacyState(null,fromDisk,dictionaryResults).state;
 }else if(disk.libraries.length||storage.usesSourceRoot()){
  for(const lib of disk.libraries){const previous=state.libraries.find(l=>l.id===lib.id);for(const word of lib.words){const old=previous?.words.find(w=>w.language===word.language&&comparison(w.word,w.language)===comparison(word.word,word.language));if(old)for(const key of['errorCount','testTotal','testCorrect'])word[key]=old[key];}}
  state=sanitizeState({...state,libraries:[...state.libraries.filter(l=>l.builtin),...disk.libraries],folders:disk.folders,activeLibrary:disk.libraries[0]?.id||state.libraries.find(l=>l.builtin)?.id});
 }
 if(!disk.managed&&disk.libraries.length)await storage.setSourceRoot(true);
 storage.markDirectoryLoaded();$('storage-status').textContent=bi("统一保存目录","Save folder");$('storage-summary').textContent=storage.currentDirectory().name+bi(" · 已读取文件夹内容"," · Folder contents loaded");return true;
}
async function connectLearningDirectory(reconnect=false){
 pause();clearTimeout(syncTimer);
 // Keep the picker/permission request directly within the user's click.
 const handle=reconnect?await storage.reconnectDirectory():await storage.chooseDirectory();await storage.flushDirectory();
 workspaceLoading=true;$('workspace').inert=true;
 try{await readConnectedDirectory();selectLibrary(state.activeLibrary);journey?.refresh();skins?.refresh();}
 finally{workspaceLoading=false;$('workspace').inert=false;}
 persist();await storage.syncDirectory(state);return handle;
}
async function beforeAccountChange(){
 if(querying)throw new Error(bi("单词正在导入，请完成后再切换账号","Words are being imported. Wait until the import finishes before switching accounts."));
 pause();journey?.close();clearTimeout(syncTimer);await saveNow();
 if(storage.currentDirectory())await storage.syncDirectory(state);
 await storage.flushDirectory();
}
async function switchWorkspace(user,meta={}){
 if(meta.profileOnly||(user?.id||null)===(accountUser?.id||null)&&!workspaceLoading){accountUser=user;return;}
 const oldScope=storage.currentProfileScope(),oldState=structuredClone(state),oldDirectory=storage.currentDirectory(),oldSourceRoot=storage.usesSourceRoot();
 if(!workspaceLoading)await beforeAccountChange();
 workspaceLoading=true;$('workspace').inert=true;accountUser=user;onboarding?.setUser(user);voice.stop();wordTransition.cancel();journey?.close();
 try{
  await storage.setProfileScope(user?.id);let saved=await cachedWorkspace();
  // The first local administrator keeps the existing guest workspace. Other accounts start separately.
  if(!saved&&user?.role==='admin'&&oldScope==='guest'&&oldState.libraries.length){saved=oldState;if(oldDirectory)await storage.adoptDirectory(oldDirectory,oldSourceRoot);}
  let legacy=null;if(!saved&&!user)try{legacy=localStorage.getItem('blind_dict_v20_optimized_test');}catch{}
  state=migrateLegacyState(legacy,saved,dictionaryResults).state;
  await storage.restoreDirectory();
  $('storage-status').textContent=accountUser?bi("个人空间","Personal space"):bi("本地存储","Local storage");$('storage-summary').textContent=bi("词库与进度自动保存","Libraries and progress saved automatically");
  try{await readConnectedDirectory();}catch(error){$('storage-summary').textContent=bi("文件夹读取失败 · 暂停目录写入","Folder could not be read · Folder writes paused");toast(error.message);}
  state.settings.voice='recorded';state.settings.freeFallback=state.settings.freeFallback!==false;
  queue=[];queueIndex=0;test=null;historySession=null;collapsedFolders.clear();$('word-search').value='';$('library-search').value='';$('word-input').value='';
  resetAnswer();selectLibrary(state.activeLibrary);journey?.refresh();skins?.refresh();
 }finally{workspaceLoading=false;$('workspace').inert=false;}
 persist();await welcomeIfReady();
}
async function welcomeIfReady(){
 if(welcomeRunning||workspaceLoading||document.hidden||document.querySelector('dialog[open]')||onboarding?.isOpen())return;
 welcomeRunning=true;
 try{if(await onboarding?.offerIfNeeded())return;if(!workspaceLoading&&!document.querySelector('dialog[open]')&&!onboarding?.isOpen())await journey?.maybeShowIntro();}
 finally{welcomeRunning=false;}
}
async function init(){
 $('workspace').inert=true;
 onboarding=createOnboarding({button:$('onboarding-button'),onBeforeOpen:async()=>{pause();journey?.close();skins?.close();accountUI?.close();if($('modal').open)closeModal();if(document.fullscreenElement)await document.exitFullscreen().catch(()=>{});},onClose:()=>setTimeout(()=>welcomeIfReady().catch(()=>{}),80)});
 accountUI=createAccountUI({button:$('account-button'),onBeforeChange:beforeAccountChange,onSessionChange:switchWorkspace,canResume:()=>!workspaceLoading&&!querying,toast,getDirectoryStatus:()=>storage.currentDirectory()?.name||bi("尚未选择本机文件夹","No local folder selected"),chooseDirectory:()=>connectLearningDirectory(!!storage.currentDirectory())});
 journey=createJourney({getData:()=>state.journey,setData:async data=>{state.journey=normalizeJourney(data);persist();await saveNow();},getMotion:()=>state.settings.motion,toast});journey.mount($('journey-button'));
 skins=createSkins({getSkin:()=>state.settings.skin,setSkin:async id=>{state.settings.skin=id;persist();await saveNow();},getMotion:()=>state.settings.motion,getOptions:()=>state.settings.scenery,setOptions:options=>{state.settings.scenery=normalizeSceneryOptions(options);persist();},toast,videos:{carousel:'assets/skins/carousel.mp4',forest:'assets/skins/forest.mp4'}});skins.mount();
 $('account-button').addEventListener('click',()=>{pause();journey.close();},true);
 $('journey-button').addEventListener('click',()=>pause(),true);
 const [results,user]=await Promise.all([loadDictionary(),accountUI.initialize()]);dictionaryResults=results;
 createStars();await switchWorkspace(user);
 if(innerWidth<=700)$('workspace').classList.add('sidebar-collapsed');
 if(results.length<5)toast(bi("部分内置词库未加载，请检查连接后刷新","Some built-in libraries did not load. Check your connection and refresh."));
 initializeRecordings();
}
document.addEventListener('close',()=>setTimeout(()=>welcomeIfReady().catch(()=>{}),60),true);
window.addEventListener('focus',()=>{if(!workspaceLoading&&!querying&&!document.querySelector('dialog[open]'))accountUI?.refresh().catch(()=>{});});
setInterval(()=>{if(!document.hidden&&!workspaceLoading&&!querying&&!document.querySelector('dialog[open]'))accountUI?.refresh().catch(()=>{});},60000);
init().catch(error=>{workspaceLoading=false;$('workspace').inert=false;render();toast(bi("页面初始化未完成：","The page could not finish loading: ")+error.message);});
setInterval(()=>{if(['http:','https:'].includes(location.protocol)&&['127.0.0.1','localhost','[::1]'].includes(location.hostname))fetch(new URL('/api/health',location.href),{cache:'no-store',signal:AbortSignal.timeout(3000)}).catch(()=>{});},60000);
